			if hit then pk[#pk + 1] = string.format("%.0f:%d:%.1f:%.2f", z, s, y, math.abs(hit.Position.X - cx)) end
		end
	end
	if #out == 24 then print("QQ C1 RIM " .. table.concat(out, " ")); out = {} end
	if #pk >= 24 then print("QQ C1 HIT " .. table.concat(pk, " ")); pk = {} end
